//! 移行した既存表の `id` 列へ IDENTITY 相当の SEQUENCE を割り当てる部品（TABLE-23 (8)・
//! TABLE-24 (1)〜(4)・RECOVER-1 のポインタ。Issue #1698。親: #1696。設計記録:
//! `docs/design/migrated-id-identity.md` D2・D4）。
//!
//! 役割: #2200 の移行処理が表ごとに呼ぶ `pub(crate)` の部品で、移行した表の `id` 列へ
//! `<table>_id_seq` の SEQUENCE と `GENERATED BY DEFAULT AS IDENTITY` 相当の DEFAULT を割り当てる。
//! 初期状態・原子性・再実行条件の具体は spec のポインタ（TABLE-24 (1)〜(4)・RECOVER-1・
//! RECOVER-10〜12）に従い、本ファイルのコードで実現する（契約の文言は転記しない）。
//!
//! 呼び出し元: #2200 の移行 txn（結線は #2200 の範囲。本ファイルは SQL・NoSQL・公開 API のいずれにも
//! 結線せず、外から見える挙動を変えない）。呼び出し先: 親モジュールの SEQUENCE 作成・命名・所有者
//! 設定・状態行の書き込みと、`catalog.rs` のスキーマ保存。
//!
//! テナント境界（P0）: 状態行のキー先頭は `tenant_id` で、初期値は自テナントの最大 `id` だけから
//! 決まる。他テナントの件数・最大値は採番値にも `2200H` の有無にもエラー文言にも現れない。DDL は
//! PolicyContext を取らない移行処理なので、母集合は全テナント（可視集合へ縮めない）。
//!
//! fail-closed: 前提の不一致（`id` 列の型・PK・既存 DEFAULT・所有者の食い違い）は黙って直さず
//! 固定文言の `Invalid` で拒否し、拒否時は何も書かない。`i64::MAX` を超える従来の u64 `id` は
//! `i64::MAX` へ飽和させ、次の採番を `2200H`（`LimitReached`）で止めて衝突させない。

use std::collections::BTreeMap;
use std::ops::Bound;

use redb::ReadableTable;

use crate::catalog::{
    get_table_schema_in_txn_impl, map_row_table_error, user_rows_table_def, user_rows_table_name,
    validate_identifier, CatalogError, ColumnDefault, ColumnType, IdentityKind, Result, Storage,
    TableSchema,
};
use crate::row_codec::{scan_scalar_columns, ScalarRef};
use crate::storage::read_source::ReadSource;

use super::{
    choose_implicit_sequence_name_in_txn, create_sequence_in_txn, decode_sequence_def_with_owner,
    load_sequence_bytes_in_txn, set_sequence_owner_in_txn, write_state_in_txn, SeqCursor,
    SequenceOwner, SequenceParams, MAX_CURSORS,
};

/// 移行する `id` 列の名前（ADR D2。PK 列名は移行後も `id`）。
const ID_COLUMN: &str = "id";

/// [`assign_migrated_id_identity_in_txn`] の結果。
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum MigratedIdIdentityOutcome {
    /// 新たに SEQUENCE を作り列へ結び付けた（`sequence` はその名前）。
    Assigned { sequence: String },
    /// 既に割り当て済み。何も書いていない（再実行で収束した）。
    AlreadyAssigned { sequence: String },
}

/// 移行 SEQUENCE の定義（ADR D2）。`MINVALUE 1`・`MAXVALUE` は bigint の最大値・`NO CYCLE`。
fn migrated_sequence_params() -> SequenceParams {
    SequenceParams {
        increment: 1,
        min_value: 1,
        max_value: i64::MAX,
        start: 1,
        cycle: false,
    }
}

fn invalid(msg: &str) -> CatalogError {
    CatalogError::Invalid(msg.to_string())
}

/// 表の `id` 列への割り当て前提を検証する（書き込みより前に行い、拒否時の副作用をゼロにする）。
/// 割り当て済みなら `Some(SEQUENCE 名)`、未割り当てで前提を満たすなら `None`。
fn check_preconditions(
    write_txn: &redb::WriteTransaction,
    schema: &TableSchema,
) -> Result<Option<String>> {
    let column = schema
        .columns
        .iter()
        .find(|c| c.name == ID_COLUMN)
        .ok_or_else(|| invalid("migrated id column does not exist"))?;
    if column.ty != ColumnType::BigInt {
        return Err(invalid("migrated id column must be BIGINT"));
    }
    if schema.primary_key() != Some([ID_COLUMN.to_string()].as_slice()) {
        return Err(invalid("migrated id column must be the primary key"));
    }
    match &column.default_expr {
        None => Ok(None),
        Some(ColumnDefault::Identity {
            sequence,
            kind: IdentityKind::ByDefault,
        }) => {
            // 割り当て済みとみなすには、SEQUENCE が存在し所有者が `(table, id)` であること。
            let bytes = load_sequence_bytes_in_txn(write_txn, sequence)
                .map_err(|_| invalid("migrated id sequence is inconsistent"))?;
            let (_, owner) = decode_sequence_def_with_owner(&bytes)?;
            let expected = SequenceOwner {
                table: schema.name.clone(),
                column: ID_COLUMN.to_string(),
            };
            if owner.as_ref() == Some(&expected) {
                Ok(Some(sequence.clone()))
            } else {
                Err(invalid("migrated id sequence is inconsistent"))
            }
        }
        Some(_) => Err(invalid(
            "migrated id column already has a different DEFAULT",
        )),
    }
}

/// `id` が物理キー（rowid）と同一の表か、列に格納した値かで走査経路を選び、テナントごとの
/// 最大 `id`（`i64`）を返す。経路 (a) は物理キーをテナント単位で飛ばし読みし（O(テナント数 × log n)）、
/// `i64::MAX` を超える u64 は `i64::MAX` へ飽和させる。経路 (b) は行を 1 回走査して `id` 列を
/// 復号する（既存データ量に比例する一度きりの処理。NULL・型違いは `CorruptSchema` で fail-closed）。
/// 行ストアが未作成なら空。テナント数は [`MAX_CURSORS`] で打ち切る（無制限確保の防止）。
pub(crate) fn per_tenant_max_id_in_txn(
    write_txn: &redb::WriteTransaction,
    schema: &TableSchema,
) -> Result<Vec<(String, i64)>> {
    let row_table_name = user_rows_table_name(&schema.name);
    let def = user_rows_table_def(&row_table_name);
    let table = match ReadSource::open_table(write_txn, def) {
        Ok(t) => t,
        Err(redb::TableError::TableDoesNotExist(_)) => return Ok(Vec::new()),
        Err(e) => return Err(map_row_table_error(e)),
    };
    let too_many = || CatalogError::ViewLimitExceeded("too many tenants".to_string());
    let corrupt = || CatalogError::CorruptSchema("corrupt row store entry".to_string());

    if schema.has_pseudo_id() {
        // 経路 (a): 物理キー = id。各テナントの範囲の末尾キーを取り、次のテナントへ飛ぶ。
        let mut out: Vec<(String, i64)> = Vec::new();
        let mut after: Option<String> = None;
        loop {
            let start = match &after {
                Some(t) => Bound::Excluded((t.as_str(), u64::MAX)),
                None => Bound::Unbounded,
            };
            let next_tenant: Option<String> = match table
                .range::<(&str, u64)>((start, Bound::Unbounded))?
                .next()
            {
                Some(entry) => Some(entry?.0.value().0.to_string()),
                None => None,
            };
            let Some(tenant) = next_tenant else {
                return Ok(out);
            };
            if out.len() >= MAX_CURSORS {
                return Err(too_many());
            }
            let last = match table
                .range::<(&str, u64)>((tenant.as_str(), 0)..=(tenant.as_str(), u64::MAX))?
                .next_back()
            {
                Some(entry) => entry?.0.value().1,
                None => return Err(corrupt()),
            };
            out.push((tenant.clone(), i64::try_from(last).unwrap_or(i64::MAX)));
            after = Some(tenant);
        }
    }

    // 経路 (b): rowid と id が別。行ごとに id 列を復号してテナント別の最大値を集める。
    let index = schema
        .columns
        .iter()
        .position(|c| c.name == ID_COLUMN)
        .ok_or_else(|| invalid("migrated id column does not exist"))?;
    let mut maxima: BTreeMap<String, i64> = BTreeMap::new();
    for entry in table.iter()? {
        let (k, v) = entry?;
        let key_tenant = k.value().0;
        let raw = v.value();
        let (hdr_tenant, _vis, offset) =
            crate::storage::decode_row_header(raw).map_err(|_| corrupt())?;
        if hdr_tenant != key_tenant {
            return Err(corrupt());
        }
        let mut scratch: Vec<f32> = Vec::new();
        let (_dim, metadata) = crate::storage::decode_row_body_into(raw, offset, &mut scratch)
            .map_err(|_| corrupt())?;
        let scanned = scan_scalar_columns(schema, metadata).map_err(|_| corrupt())?;
        let id = match scanned.get(index) {
            Some(Some(ScalarRef::BigInt(v))) => *v,
            _ => return Err(corrupt()),
        };
        match maxima.get_mut(key_tenant) {
            Some(m) => *m = (*m).max(id),
            None => {
                if maxima.len() >= MAX_CURSORS {
                    return Err(too_many());
                }
                maxima.insert(key_tenant.to_string(), id);
            }
        }
    }
    Ok(maxima.into_iter().collect())
}

/// 移行する表 `table` の `id` 列へ IDENTITY 相当の SEQUENCE を割り当てる write txn 内本体。
/// begin・commit は含まない（#2200 の移行 txn に載せる）。表の世代 bump は呼び出し側が commit 直前に
/// 行う（`create_table_with_implicit_sequences_in_txn` と同じ契約）。`Err` の場合は呼び出し側が txn を
/// 破棄すること（途中まで作った SEQUENCE も残らない）。前提検証はすべて書き込みより前なので、
/// 前提不一致の `Err` では何も書いていない。
///
/// 手順（ADR D2・D4）: 前提検証 → `<table>_id_seq`（衝突時 `seq1`…）の作成 → `id` 列の DEFAULT を
/// `Identity { ByDefault }` へ → 所有者 `(table, id)` の設定 → テナントごとの状態行
/// `{ last_value: 最大 id, is_called: true }`（`最大 id >= 1` のテナントのみ。行の無いテナントは
/// 状態行なしで初回が START = 1 から始まる）。新しい SEQUENCE は内部 ID が新規で
/// `SequenceAllocator` にカーソルが無いため、初回の払い出しは本 txn の状態行から始まる
/// （メモリの破棄は不要）。
#[cfg_attr(not(test), allow(dead_code))] // #2200 の移行 txn が呼ぶ（結線は #2200）。
pub(crate) fn assign_migrated_id_identity_in_txn(
    write_txn: &redb::WriteTransaction,
    table: &str,
) -> Result<MigratedIdIdentityOutcome> {
    validate_identifier(table)?;
    let schema = get_table_schema_in_txn_impl(write_txn, table, true)?;
    if let Some(sequence) = check_preconditions(write_txn, &schema)? {
        return Ok(MigratedIdIdentityOutcome::AlreadyAssigned { sequence });
    }
    // 状態行の初期値は SEQUENCE 作成より前に算出する（走査の失敗で何も書かないため）。
    let maxima = per_tenant_max_id_in_txn(write_txn, &schema)?;

    let name = choose_implicit_sequence_name_in_txn(write_txn, table, ID_COLUMN, &[])?;
    let sequence_id = create_sequence_in_txn(write_txn, &name, &migrated_sequence_params())?;

    let mut updated = schema.clone();
    for c in updated.columns.iter_mut() {
        if c.name == ID_COLUMN {
            c.set_default_expr(Some(ColumnDefault::Identity {
                sequence: name.clone(),
                kind: IdentityKind::ByDefault,
            }));
        }
    }
    crate::catalog::write_schema_in_txn(write_txn, &updated)?;
    // 列の実在を確かめるため、スキーマ更新の後に所有者を設定する。
    set_sequence_owner_in_txn(
        write_txn,
        &name,
        Some(SequenceOwner {
            table: table.to_string(),
            column: ID_COLUMN.to_string(),
        }),
    )?;
    for (tenant, max_id) in &maxima {
        if *max_id >= 1 {
            write_state_in_txn(
                write_txn,
                tenant,
                sequence_id,
                &SeqCursor {
                    last_value: *max_id,
                    is_called: true,
                },
            )?;
        }
    }
    Ok(MigratedIdIdentityOutcome::Assigned { sequence: name })
}

impl Storage {
    /// [`assign_migrated_id_identity_in_txn`] を単独の write txn で実行する（世代 bump・commit 込み）。
    /// 一時表の Storage は永続 DB の SEQUENCE を解決できないため `Invalid` で拒否する（移行の対象外）。
    /// 再実行は冪等で、`AlreadyAssigned` のときは commit せず世代も進めない。
    #[cfg_attr(not(test), allow(dead_code))] // #2200 の移行 txn が in_txn 版を呼ぶ。テスト・結線の入口。
    pub(crate) fn assign_migrated_id_identity(
        &self,
        table: &str,
    ) -> Result<MigratedIdIdentityOutcome> {
        if self.is_temp_scoped() {
            return Err(invalid(
                "migrated id identity is not supported for temp tables",
            ));
        }
        let write_txn = self
            .begin_write_txn()
            .map_err(crate::catalog::convert_storage_error)?;
        let outcome = assign_migrated_id_identity_in_txn(&write_txn, table)?;
        if matches!(outcome, MigratedIdIdentityOutcome::AlreadyAssigned { .. }) {
            return Ok(outcome);
        }
        crate::catalog::bump_table_generation_in_txn(&write_txn, table)?;
        crate::recovery::commit_boundary::commit(write_txn)
            .map_err(crate::catalog::convert_storage_error)?;
        Ok(outcome)
    }
}

